"use client";

import { cn } from "@/lib/utils";
import React, { useEffect, useMemo, useRef } from "react";
import { springLinear } from "./motion-curves";

export type NetworkNode = {
  id: string;
  ring: number; // 1 (inner), 2 (middle), 3 (outer), etc.
  image?: string;
  fallback?: string;
  label?: string;
  size?: "sm" | "md" | "lg" | (string & {});
};

export interface NetworkGraphProps
  extends React.HTMLAttributes<HTMLDivElement> {
  nodes: NetworkNode[];
  centerNode?: {
    image?: string;
    fallback?: string;
    label?: string;
  };
  ringCount?: number;
  baseRadius?: number; // Starting radius percentage for the first ring
  ringGap?: number; // Percentage gap between rings
  animateIn?: boolean;
  animateOrbit?: boolean; // Toggles planetary orbital motion
  orbitSpeed?: number; // Speed multiplier (1 = default, 2 = twice as fast)
}

// The entrance springs as CSS `linear()` curves, generated from the same
// stiffness/damping the springs had, so they settle exactly as before.
const CENTER_SPRING = springLinear({ stiffness: 200, damping: 20 });
const NODE_SPRING = springLinear({ stiffness: 260, damping: 20 });

const keyframes = `
@keyframes network-graph-ring-in { from { opacity: 0; scale: 0.8; } }
@keyframes network-graph-pop-in { from { opacity: 0; scale: 0; } }
`;

const sizeMap = {
  sm: "w-6 h-6 sm:w-9 sm:h-9",
  md: "w-8 h-8 sm:w-11 sm:h-11",
  lg: "w-10 h-10 sm:w-14 sm:h-14",
};

export const NetworkGraph = React.forwardRef<HTMLDivElement, NetworkGraphProps>(
  (
    {
      nodes,
      centerNode,
      ringCount = 3,
      baseRadius = 15,
      ringGap = 15,
      animateIn = true,
      animateOrbit = true,
      orbitSpeed = 1,
      className,
      ...props
    },
    ref,
  ) => {
    const rings = Array.from({ length: ringCount }, (_, i) => i + 1);

    // FIXED: Added [nodes] dependency array to useMemo to resolve ts(2554) and eslint warnings
    const groupedNodes = useMemo(() => {
      const groups: Record<number, NetworkNode[]> = {};
      nodes.forEach((node) => {
        if (!groups[node.ring]) groups[node.ring] = [];
        groups[node.ring].push(node);
      });
      return groups;
    }, [nodes]);

    return (
      <div
        ref={ref}
        className={cn(
          "relative w-full aspect-square max-w-[800px] mx-auto flex items-center justify-center",
          className,
        )}
        {...props}
      >
        <style>{keyframes}</style>

        {/* Render Rings */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          {rings.map((ring) => {
            const radius = baseRadius + (ring - 1) * ringGap;
            return (
              <div
                key={`ring-${ring}`}
                className="absolute rounded-full border border-primary/[0.08]/[0.08]"
                style={{
                  width: `${radius * 2}%`,
                  height: `${radius * 2}%`,
                  animation: animateIn
                    ? `network-graph-ring-in 0.8s cubic-bezier(0, 0, 0.58, 1) ${ring * 0.1}s backwards`
                    : undefined,
                }}
              />
            );
          })}
        </div>

        {/* Render Nodes per Ring with Orbiting Container */}
        {rings.map((ringIndex) => (
          <OrbitRing
            key={`ring-orbit-${ringIndex}`}
            ringIndex={ringIndex}
            nodes={groupedNodes[ringIndex] || []}
            radius={baseRadius + (ringIndex - 1) * ringGap}
            animateIn={animateIn}
            animateOrbit={animateOrbit}
            orbitSpeed={orbitSpeed}
          />
        ))}

        {/* Center Node */}
        {centerNode && (
          <div className="absolute z-20 w-0 h-0 flex items-center justify-center left-1/2 top-1/2">
            <div
              className="relative group cursor-pointer"
              style={{
                animation: animateIn
                  ? `network-graph-pop-in ${CENTER_SPRING.duration}ms ${CENTER_SPRING.easing} backwards`
                  : undefined,
              }}
            >
              <div className="w-12 h-12 sm:w-16 sm:h-16 md:w-20 md:h-20 rounded-full border-[3px] sm:border-[5px] border-white dark:border-[#0a0a0a] shadow-xl overflow-hidden bg-card flex items-center justify-center transition-transform duration-300 group-hover:scale-105">
                {centerNode.image ? (
                  <img
                    src={centerNode.image}
                    alt={centerNode.label || "Center"}
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <span className="text-xs sm:text-sm font-semibold text-muted-foreground uppercase">
                    {centerNode.fallback}
                  </span>
                )}
              </div>
              {centerNode.label && (
                <div className="absolute top-[calc(100%+10px)] sm:top-[calc(100%+14px)] left-1/2 -translate-x-1/2 whitespace-nowrap px-3 py-1 sm:py-1.5 rounded-full bg-primary text-primary-foreground text-[10px] sm:text-xs font-semibold shadow-sm z-50">
                  {centerNode.label}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  },
);
NetworkGraph.displayName = "NetworkGraph";

/**
 * One orbit and the avatars riding it.
 *
 * Rotation is advanced by hand each frame instead of being handed to a
 * `repeat: Infinity` tween, because a tween reads its `duration` only when it
 * STARTS: with a constant `rotate` target the animation never restarts, so a
 * later `orbitSpeed` change was silently ignored unless the whole graph was
 * remounted. Stepping the value per frame makes the speed change apply on the
 * very next frame, from wherever the ring currently is — no jump, no remount.
 */
function OrbitRing({
  ringIndex,
  nodes,
  radius,
  animateIn,
  animateOrbit,
  orbitSpeed,
}: {
  ringIndex: number;
  nodes: NetworkNode[];
  radius: number;
  animateIn: boolean;
  animateOrbit: boolean;
  orbitSpeed: number;
}) {
  const ringRef = useRef<HTMLDivElement>(null);

  // Outer rings take longer per lap, and even rings run backwards for depth.
  const baseDuration = (35 + ringIndex * 10) / (orbitSpeed || 1);
  const direction = ringIndex % 2 === 0 ? -1 : 1;
  const degreesPerSecond = animateOrbit ? (360 / baseDuration) * direction : 0;

  // Read through a ref so the frame callback always sees the latest speed
  // without being torn down and rebuilt on every render.
  const speedRef = useRef(degreesPerSecond);
  useEffect(() => {
    speedRef.current = degreesPerSecond;
  });

  // The ring's angle lives outside React so a speed change carries on from
  // wherever the ring is.
  const angleRef = useRef(0);
  const orbiting = degreesPerSecond !== 0;

  useEffect(() => {
    const el = ringRef.current;
    if (!el || !orbiting) return;

    let frame = 0;
    let last = 0;
    const tick = (now: number) => {
      // Same frame delta as a motion frame loop: 1/60s on the first frame,
      // then the real gap clamped to 1–40ms so a stalled tab doesn't jump.
      const delta = last ? Math.min(Math.max(now - last, 1), 40) : 1000 / 60;
      last = now;
      const speed = speedRef.current;
      // Wrapped at a full turn so the value stays small over a long session.
      const angle = (angleRef.current + (speed * delta) / 1000) % 360;
      angleRef.current = angle;
      el.style.transform = `rotate(${angle}deg)`;
      // Every avatar on the ring shares one counter-rotation, which is what
      // keeps faces upright while the ring itself turns.
      el.style.setProperty("--network-graph-counter", `rotate(${-angle}deg)`);
      frame = requestAnimationFrame(tick);
    };
    const start = () => {
      if (frame) return;
      last = 0;
      frame = requestAnimationFrame(tick);
    };
    const stop = () => {
      cancelAnimationFrame(frame);
      frame = 0;
    };

    // Nobody sees a ring turning off screen, so the loop only runs on screen.
    if (typeof IntersectionObserver === "undefined") {
      start();
      return stop;
    }
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) start();
      else stop();
    });
    observer.observe(el);
    return () => {
      observer.disconnect();
      stop();
    };
  }, [orbiting]);

  const angleStep = 360 / nodes.length;

  return (
    <div ref={ringRef} className="absolute inset-0 pointer-events-none">
      {nodes.map((node, index) => {
        const angle = angleStep * index - 90;
        const radian = (angle * Math.PI) / 180;
        const x = `calc(50% + ${radius * Math.cos(radian)}%)`;
        const y = `calc(50% + ${radius * Math.sin(radian)}%)`;

        return (
          <div
            key={node.id}
            className="absolute z-10 w-0 h-0 flex items-center justify-center pointer-events-auto"
            style={{ left: x, top: y }}
          >
            {/* 1. Entrance Scale & Opacity Wrapper */}
            <div
              style={{
                animation: animateIn
                  ? `network-graph-pop-in ${NODE_SPRING.duration}ms ${NODE_SPRING.easing} ${0.2 + ringIndex * 0.1 + index * 0.05}s backwards`
                  : undefined,
              }}
            >
              {/* 2. Counter-Rotation Wrapper (Keeps Avatars Upright!) */}
              <div
                className="relative group cursor-pointer"
                style={{ transform: "var(--network-graph-counter, none)" }}
              >
                <div
                  className={cn(
                    "relative rounded-full flex items-center justify-center overflow-hidden border border-white dark:border-[#0a0a0a] shadow-[0_2px_10px_rgba(0,0,0,0.08)] dark:shadow-[0_2px_10px_rgba(0,0,0,0.4)] transition-transform duration-300 group-hover:scale-110 group-hover:z-50 bg-card",
                    sizeMap[node.size as keyof typeof sizeMap] ?? sizeMap.md,
                  )}
                >
                  {node.image ? (
                    <img
                      src={node.image}
                      alt={node.label || "Avatar"}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <span className="text-[10px] sm:text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                      {node.fallback}
                    </span>
                  )}
                </div>

                {node.label && (
                  <div className="absolute top-[calc(100%+8px)] left-1/2 -translate-x-1/2 whitespace-nowrap px-2.5 py-1 rounded-md bg-primary text-primary-foreground text-[10px] sm:text-[11px] font-semibold shadow-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-50">
                    {node.label}
                  </div>
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Framer Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Framer's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Framer
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Framer's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Framer cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Framer Motion's named eases, as the cubic-beziers they are. */
export const FRAMER_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Framer Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Framer default 100. */
  stiffness?: number;
  /** Framer default 10. */
  damping?: number;
  /** Framer default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Framer Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Framer's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Framer's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
